/** Extract visible glyphs for first-screen font subset preloading. */
export function visibleFontText(html: string): string {
  // Exclude scripts, SVG paths/titles and CSS. Backreference must match the
  // opening element: the old /\\u0001/ accidentally matched a control char.
  // HTML generated by React is well formed, so a matching closing tag exists.
  return html
    .replace(/<(script|svg|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, "")
    .replace(/<[^>]+>/g, "")
    .slice(0, 1600);
}
